"""Write docs/labs/mixing/SOURCES.md from convert.py's --report JSON: the
owner's source list per guide (kept OFF the learner's screen, owner ruling
2026-10-04) and the per-guide conversion log.
Usage: python sources_doc.py <report.json> <out.md>"""
import json, sys

rep = json.load(open(sys.argv[1], encoding="utf-8"))
out = [
    "# Mixing Guides — sources and conversion log",
    "",
    "Generated by `scripts/mixing-guides/sources_doc.py` from the conversion report.",
    "The sources are the owner's own research, copied from each guide's **Sources** section",
    "(assets/Mixing-Guides-50-Styles, read only). They are never shown in the app.",
    "",
]
for g in rep:
    out.append(f"## {g['num']:02d} · {g['title']}")
    out.append("")
    out.append(f"- Copy edits applied: {g['edits']}")
    for line in g["log"]:
        out.append(f"- Structure: {line}")
    if g["empty"]:
        out.append(f"- Empty sections: {', '.join(g['empty'])}")
    out.append("")
    for s in g["sources"]:
        out.append(f"1. {s}")
    out.append("")
open(sys.argv[2], "w", encoding="utf-8", newline="\n").write("\n".join(out))
print("wrote", sys.argv[2])
